/* Présentation d'adresse sans réécrire les anciennes fiches. */
(function(root){function lines(p){const name=[p.lastName,p.firstName].filter(Boolean).join(' ').trim()||String(p.name||'Nom et prénom à renseigner');let street=String(p.address||'').trim().split(/\r?\n/).map(s=>s.trim()).filter(Boolean);let postal=String(p.postalCode||'').trim(),city=String(p.city||'').trim();if(!postal&&!city&&street.length){const last=street[street.length-1],separate=last.match(/^(\d{5})\s+(.+)$/),inline=last.match(/^(.+?)\s+(\d{5})\s+([^\d]+)$/);if(separate){postal=separate[1];city=separate[2];street.pop();}else if(inline){street[street.length-1]=inline[1];postal=inline[2];city=inline[3];}}return{name,street:street.length?street:['Adresse à renseigner'],locality:[postal,city].filter(Boolean).join(' ')||'Code postal et ville à renseigner'};}const api={lines};root.EmployeeAddress=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;})(typeof globalThis!=='undefined'?globalThis:this);
